/**
 * PLACE-02 phase B (NEC-93): the client's proof check against the node's own vector
 * (tests/vectors/place02_registry_proof.json, generated by ethapi TestRegistryProofVector). The sealed answer's proof
 * verifies against the sealed stateRoot; the same page proven at the HEAD does not (the design's phase B mutant, "a
 * proof for the head instead of rootBlock", RED on the client side); a served record that differs from the proven one,
 * and an account whose code is not the reviewed registry, are refused.
 */
import * as fs from 'fs';
import * as path from 'path';
import { verifyRegistryProof, verifyMptProof, providerSlot, PROVIDER_REGISTRY_RUNTIME_CODE_HASH } from '../src/ddb-proof';

const vec = JSON.parse(fs.readFileSync(path.join(__dirname, 'vectors', 'place02_registry_proof.json'), 'utf8'));
const sealed = vec.sealed;

describe('PLACE-02 registry proof', () => {
  test('the code hash constant is the node\'s', () => {
    expect(PROVIDER_REGISTRY_RUNTIME_CODE_HASH).toBe(vec.registryCodeHash);
  });

  test('the sealed proof verifies against the sealed root and decodes to the records served', () => {
    const v = verifyRegistryProof(sealed.stateRoot, vec.registry, sealed.proof, sealed.providers);
    expect(v).toEqual({ valid: true });
  });

  test('a proof taken at the head does not verify against the sealed root', () => {
    const v = verifyRegistryProof(sealed.stateRoot, vec.registry, { block: 200, stateRoot: sealed.stateRoot, account: vec.headAccount }, sealed.providers);
    expect(v.valid).toBe(false);
  });

  test('a served record that is not the proven one is refused', () => {
    const tampered = JSON.parse(JSON.stringify(sealed.providers));
    tampered[0].record.offered = '0x1';
    const v = verifyRegistryProof(sealed.stateRoot, vec.registry, sealed.proof, tampered);
    expect(v.valid).toBe(false);
    expect(v.reason).toMatch(/differs/);
  });

  test('an account that is not the reviewed registry is refused', () => {
    const v = verifyRegistryProof(sealed.stateRoot, vec.registry, sealed.proof, sealed.providers, { registryCodeHash: '0x' + '11'.repeat(32) });
    expect(v.valid).toBe(false);
  });

  test('a proof node that is not the one its parent references is refused', () => {
    const p = sealed.proof.account.storageProof[0];
    const nodes = p.proof.map((h: string) => Uint8Array.from(Buffer.from(h.slice(2), 'hex')));
    nodes[nodes.length - 1][nodes[nodes.length - 1].length - 1] ^= 1;
    expect(() => verifyMptProof(Uint8Array.from(Buffer.from(sealed.proof.account.storageHash.slice(2), 'hex')),
      providerSlot(1), nodes)).toThrow(/not the node its parent references|trailing|rlp/);
  });
});
